38	 * to a headers-aware column family ({@code sessionKeyValueWithHeaders}). It uses
39	 * {@link DualColumnFamilyAccessor} for lazy migration when legacy data exists in the DEFAULT CF.
40	 */
41	public class RocksDBMigratingSessionStoreWithHeaders extends RocksDBStore implements HeadersBytesStore {
42	    private static final Logger log = LoggerFactory.getLogger(RocksDBMigratingSessionStoreWithHeaders.class);
43	
