58	    void openRocksDB(final DBOptions dbOptions,
59	                     final ColumnFamilyOptions columnFamilyOptions) {
60	        final List<ColumnFamilyHandle> columnFamilies = openRocksDB(
61	            dbOptions,
62	            new ColumnFamilyDescriptor(RocksDB.DEFAULT_COLUMN_FAMILY, columnFamilyOptions),
63	            new ColumnFamilyDescriptor(SESSION_STORE_HEADERS_VALUES_COLUMN_FAMILY_NAME, columnFamilyOptions)
64	        );
65	        final ColumnFamilyHandle noHeadersColumnFamily = columnFamilies.get(0);
66	        final ColumnFamilyHandle withHeadersColumnFamily = columnFamilies.get(1);
67	
68	        final RocksIterator noHeadersIter = db.newIterator(noHeadersColumnFamily);
69	        noHeadersIter.seekToFirst();
70	        if (noHeadersIter.isValid()) {
71	            log.info("Opening store {} in upgrade mode", name);
72	            cfAccessor = new DualColumnFamilyAccessor(
73	                noHeadersColumnFamily,
74	                withHeadersColumnFamily,
75	                HeadersBytesStore::convertToHeaderFormat,
76	                this
77	            );
78	        } else {
79	            log.info("Opening store {} in regular mode", name);
80	            cfAccessor = new SingleColumnFamilyAccessor(withHeadersColumnFamily);
81	            noHeadersColumnFamily.close();
82	        }
83	        noHeadersIter.close();
84	    }
