package org.apache.kafka.streams.state.internals;

import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.streams.errors.ProcessorStateException;
import org.apache.kafka.streams.state.internals.RocksDBStore.DBAccessor;

import org.rocksdb.ColumnFamilyHandle;
import org.rocksdb.RocksDBException;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Base implementation of {@link RocksDBStore.ColumnFamilyAccessor} that maintains a dedicated
 * <em>offsets</em> column family. This column family stores:
 * <ul>
 *     <li>the store's lifecycle status under the {@link #STATUS_KEY status} key ({@link #STORE_OPEN} while the
 *     store is open, {@link #STORE_CLOSED} once it has been cleanly closed), and</li>
 *     <li>the committed changelog offset for each {@link TopicPartition}, keyed by its {@code toString()}
 *     representation.</li>
 * </ul>
 *
 * Concrete subclasses provide the data column families and implement {@link #flush(DBAccessor, ColumnFamilyHandle)}
 * to flush both the data column families and the offsets column family together.
 */
abstract class AbstractColumnFamilyAccessor implements RocksDBStore.ColumnFamilyAccessor {

    static final byte[] STATUS_KEY = "status".getBytes(StandardCharsets.UTF_8);

    // The store was cleanly closed.
    private static final long STORE_CLOSED = 0L;
    // The store is currently open.
    private static final long STORE_OPEN = 1L;

    private final ColumnFamilyHandle offsetColumnFamilyHandle;
    private final AtomicBoolean storeOpen;

    AbstractColumnFamilyAccessor(final ColumnFamilyHandle offsetColumnFamilyHandle,
                                 final AtomicBoolean storeOpen) {
        this.offsetColumnFamilyHandle = offsetColumnFamilyHandle;
        this.storeOpen = storeOpen;
    }

    @Override
    public final void open(final DBAccessor accessor, final boolean ignoreInvalidState) throws RocksDBException {
        final byte[] statusBytes = accessor.get(offsetColumnFamilyHandle, STATUS_KEY);
        if (statusBytes != null && bytesToLong(statusBytes) == STORE_OPEN && !ignoreInvalidState) {
            throw new ProcessorStateException(
                "Invalid state during store open. Expected state to be either empty or closed");
        }
        storeOpen.set(true);
        accessor.put(offsetColumnFamilyHandle, STATUS_KEY, longToBytes(STORE_OPEN));
    }

    @Override
    public void close(final DBAccessor accessor) throws RocksDBException {
        try {
            accessor.put(offsetColumnFamilyHandle, STATUS_KEY, longToBytes(STORE_CLOSED));
        } finally {
            storeOpen.set(false);
            offsetColumnFamilyHandle.close();
        }
    }

    @Override
    public final void commit(final DBAccessor accessor,
                             final Map<TopicPartition, Long> changelogOffsets) throws RocksDBException {
        for (final Map.Entry<TopicPartition, Long> entry : changelogOffsets.entrySet()) {
            if (entry.getValue() != null) {
                accessor.put(
                    offsetColumnFamilyHandle,
                    entry.getKey().toString().getBytes(StandardCharsets.UTF_8),
                    longToBytes(entry.getValue()));
            }
        }
        flush(accessor, offsetColumnFamilyHandle);
    }

    @Override
    public final Long getCommittedOffset(final DBAccessor accessor, final TopicPartition partition) throws RocksDBException {
        final byte[] value = accessor.get(
            offsetColumnFamilyHandle,
            partition.toString().getBytes(StandardCharsets.UTF_8));
        return value == null ? null : bytesToLong(value);
    }

    /**
     * Flushes the data column families along with the offsets column family, so that committed offsets are
     * always consistent with the data persisted to disk.
     *
     * @param offsetColumnFamilyHandle the offsets column family handle, to be flushed alongside the data
     *                                 column families.
     */
    protected abstract void flush(final DBAccessor accessor,
                                  final ColumnFamilyHandle offsetColumnFamilyHandle) throws RocksDBException;

    private static byte[] longToBytes(final long value) {
        return ByteBuffer.allocate(Long.BYTES).putLong(value).array();
    }

    private static long bytesToLong(final byte[] bytes) {
        return ByteBuffer.wrap(bytes).getLong();
    }
}
