    /**
     * Best-effort cleanup of the native resources allocated during {@link #openDB} when opening the store
     * fails after RocksDB has already been opened. This releases the RocksDB directory lock and frees native
     * memory so that the failure does not leak resources or block subsequent open attempts.
     */
    private void closeNativeResourcesOnOpenFailure() {
        closeQuietly(cfAccessor == null ? null : cfAccessor::close);
        closeQuietly(offsetColumnFamilyHandle);
        closeQuietly(db);
        closeQuietly(userSpecifiedOptions);
        closeQuietly(wOptions);
        closeQuietly(fOptions);
        closeQuietly(filter);
        closeQuietly(cache);
        closeQuietly(statistics);

        cfAccessor = null;
        dbAccessor = null;
        offsetColumnFamilyHandle = null;
        db = null;
        userSpecifiedOptions = null;
        wOptions = null;
        fOptions = null;
        filter = null;
        cache = null;
        statistics = null;
    }

    private void closeQuietly(final AutoCloseable closeable) {
        if (closeable == null) {
            return;
        }
        try {
            closeable.close();
        } catch (final Exception e) {
            log.warn("Error while closing resource during failed open of store {}", name, e);
        }
